refentry.refsect1:
&reftitle.description;
arrayarray_count_values arrayarray
array_count_values ले array का values (जुन &integer;s वा &string;s हुनुपर्छ) लाई keys को रूपमा र array मा तिनीहरूको आवृत्तिलाई values को रूपमा प्रयोग गरी एउटा array return गर्दछ।

  &reftitle.parameters;





     array


count गरिने values को array

  &reftitle.examples;



    array_count_values को उदाहरण


<?php
$array = array(1, "hello", 1, "world", "hello");
print_r(array_count_values($array));
?>


    &example.outputs;


Array
(
    [1] => 2
    [hello] => 2
    [world] => 1
)
